    @staticmethod
    def _historical_other_taxa_denominator(
        tip: str,
        tip_set: set[str],
        tip_count: int,
    ) -> int:
        denominator = tip_count
        matched = None
        for character in tip:
            if character in tip_set and (
                matched is None or character not in matched
            ):
                denominator -= 1
                if matched is None:
                    matched = {character}
                else:
                    matched.add(character)
        return denominator

